import subprocess
from functools import wraps


def saneconsole(function):
    """
        Decorator for allowing to visibly write in console again
        :param function:
        :return:
        """

    @wraps(function)
    def wrapper(*args, **kwargs):
        returned_value = function(*args, **kwargs)
        subprocess.call('stty sane', shell=True)
        return returned_value

    return wrapper
